async Task<string> FetchDataAsync() {
    Console.WriteLine("Before await");  // runs synchronously

    string result = await httpClient.GetStringAsync("https://api.example.com");
    // Thread is FREE during this I/O wait ↑

    Console.WriteLine("After await");   // resumes after I/O completes
    return result;
}

// ── What the compiler generates (simplified) ──
class FetchDataAsyncStateMachine : IAsyncStateMachine {
    public int state;          // tracks where we paused
    public string result;      // local variable preserved
    public AsyncTaskMethodBuilder<string> builder;

    public void MoveNext() {
        switch (state) {
            case 0:
                Console.WriteLine("Before await");
                var awaiter = httpClient.GetStringAsync(url).GetAwaiter();
                if (!awaiter.IsCompleted) {
                    state = 1;  // save state
                    builder.AwaitUnsafeOnCompleted(ref awaiter, ref this);
                    return;     // return to caller, thread is free!
                }
                goto case 1;
            case 1:
                result = awaiter.GetResult();
                Console.WriteLine("After await");
                builder.SetResult(result);
                break;
        }
    }
}

